-- zycck Excel 文本迁移第一步：导入前 50 条基础职业和缺失的干扰职业。
-- 无 A-D 选项的职业类型与最终分类由 v26_zycck_excel_exploration.sql 统一修正。

-- 兼容已经执行过部分迁移的环境：字段存在时不重复添加。
SET @zycck_has_question := (
  SELECT COUNT(*) FROM information_schema.columns
  WHERE table_schema = DATABASE()
    AND table_name = 'gkzh_zycck_career_question'
    AND column_name = 'has_question'
);
SET @zycck_sql := IF(
  @zycck_has_question = 0,
  'ALTER TABLE gkzh_zycck_career_question ADD COLUMN has_question CHAR(1) NOT NULL DEFAULT ''1'' AFTER career_name',
  'SELECT 1'
);
PREPARE zycck_stmt FROM @zycck_sql;
EXECUTE zycck_stmt;
DEALLOCATE PREPARE zycck_stmt;
ALTER TABLE gkzh_zycck_career_question MODIFY option_a VARCHAR(200) DEFAULT NULL, MODIFY option_b VARCHAR(200) DEFAULT NULL, MODIFY option_c VARCHAR(200) DEFAULT NULL, MODIFY option_d VARCHAR(200) DEFAULT NULL, MODIFY option_a_career_id BIGINT DEFAULT NULL, MODIFY option_b_career_id BIGINT DEFAULT NULL, MODIFY option_c_career_id BIGINT DEFAULT NULL, MODIFY option_d_career_id BIGINT DEFAULT NULL, MODIFY correct_option_key CHAR(1) DEFAULT NULL;
UPDATE gkzh_zycck_career_question SET status='1', draw_candidate='0' WHERE status='0';
UPDATE gkzh_zycck_category SET draw_mode='fixed', status='0', update_time=NOW() WHERE code='digital_product';
UPDATE gkzh_zycck_category SET draw_mode='random', status='0', update_time=NOW() WHERE code='digital_content';
UPDATE gkzh_zycck_category SET draw_mode='fixed', status='0', update_time=NOW() WHERE code='digital_marketing';
UPDATE gkzh_zycck_category SET draw_mode='random', status='0', update_time=NOW() WHERE code='professional_service';
UPDATE gkzh_zycck_category SET draw_mode='random', status='0', update_time=NOW() WHERE code='freelance_skill';
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_product' LIMIT 1),'产品经理','1','把用户想法变成真正好用的产品','了解用户需求，思考产品应该解决什么问题，并协调设计、技术等人员，把想法逐步变成真正可使用的产品。','需求沟通｜了解用户新需求\n方案设计｜规划产品功能\n团队协作｜和研发设计讨论\n效果复盘｜分析产品使用情况','当数字产品越来越多、用户需求越来越复杂，仅靠技术或创意已经难以完成一个好产品，需要有人协调用户、技术和商业，让不同想法最终形成完整的产品。AI的发展又让产品设计、开发和验证变得更高效，进一步拓展了产品经理的工作空间。',NULL,NULL,'用户研究员','产品经理','产品运营','用户体验专员',NULL,NULL,NULL,NULL,'B',NULL,'1',1,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_product' LIMIT 1),'用户体验专员','1','让产品用起来更简单、更舒服','从用户使用产品的过程出发，发现操作不方便、体验不顺畅的地方，并提出改进建议，让产品更加简单、好用。','体验观察｜记录用户使用问题\n用户访谈｜了解真实使用感受\n问题分析｜寻找体验不佳原因\n优化建议｜提出体验改进方案','同样的产品，使用起来可能有完全不同的感受。企业越来越重视用户体验，因此需要专门的人发现问题、改善使用过程。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',2,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_product' LIMIT 1),'数据标注师','1','为AI学习准备高质量的数据素材','按照明确的规则整理和标记图片、文字、声音等数据，为人工智能学习提供准确、规范的数据素材。','数据整理｜整理待处理数据\n内容判断｜按照规则识别内容\n数据标记｜准确完成数据标注\n质量检查｜检查标注是否准确','AI需要大量真实、准确的数据才能学习和判断，但原始数据通常无法直接使用，因此产生了整理、分类和标记数据的工作。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',3,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_product' LIMIT 1),'数字内容审核专员','1','守护网络内容的规范与健康','对网络平台上的文字、图片、视频等内容进行检查，识别不合适或违规的信息，维护健康、有序的网络环境。','内容浏览｜查看平台发布内容\n风险识别｜发现不当信息\n规则判断｜按照标准进行审核\n结果记录｜记录审核处理结果','网络平台每天产生海量文字、图片和视频，需要有人识别不合适内容，维护平台秩序，也让用户拥有更加健康的网络环境。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',4,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_product' LIMIT 1),'数字人直播运营','1','让虚拟主播直播得更专业、更有趣','负责数字人的直播内容、直播流程和日常运营，让虚拟形象能够持续开展直播、互动和内容传播。','直播准备｜检查直播内容设备\n内容安排｜准备直播主题素材\n直播管理｜关注直播互动效果\n数据复盘｜分析直播表现数据','虚拟数字人逐渐进入直播、营销和娱乐等场景，但数字人也需要内容设计、运营和管理，因此产生了新的直播工作。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',5,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_product' LIMIT 1),'智能客服运营专员','1','让智能客服更懂用户、更会服务','负责优化智能客服的服务内容和回答效果，根据用户反馈不断调整，让智能客服能够更准确地解决用户问题。','问题收集｜整理用户常见问题\n话术优化｜完善客服回答内容\n效果测试｜检查AI回答效果\n反馈改进｜根据问题持续调整','企业每天面对大量重复咨询，智能客服可以提高服务效率，但仍需要人工不断优化内容和服务流程，让AI更好地帮助用户。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',6,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_product' LIMIT 1),'AI训练师','1','教AI学会理解和处理各种信息','根据任务要求整理、判断和反馈数据，帮助人工智能更准确地理解文字、图片等信息，提升AI处理问题的能力。','数据准备｜整理AI学习数据\n内容判断｜判断答案是否合理\n结果反馈｜给AI提供纠正信息\n效果检查｜观察模型表现变化','AI并不是天生就懂人类表达，需要大量数据和人工反馈进行学习，因此出现了帮助AI提高理解、判断和生成能力的工作。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',7,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_product' LIMIT 1),'用户研究员','1','通过用户反馈发现真正的需求','通过访谈、问卷、观察等方式了解用户想法和需求，为产品设计和服务改进提供真实的用户反馈。','研究准备｜确定用户研究问题\n用户访谈｜与用户交流了解需求\n信息整理｜整理用户反馈信息\n研究分析｜发现用户真实需求','企业不能只凭自己的想法开发产品，需要真正了解用户的需求和习惯，因此产生了专门研究用户、帮助企业做决策的职业。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',8,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_product' LIMIT 1),'产品运营','1','让产品被更多用户发现和使用','围绕产品开展推广、活动和用户维护等工作，了解用户使用情况，让产品获得更多用户并持续活跃。','用户观察｜了解用户使用情况\n活动策划｜设计用户参与活动\n内容推广｜推动产品获得关注\n数据复盘｜分析运营效果','好产品并不意味着自然会被用户发现，企业需要通过推广、活动和用户维护让产品持续成长，因此形成了产品运营岗位。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',9,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_product' LIMIT 1),'体验运营专员','1','让用户从使用到服务都有好体验','关注用户从接触产品到使用服务的全过程，通过活动、反馈和服务优化，让用户获得更加顺畅、满意的体验。','用户反馈｜收集用户使用意见\n流程观察｜寻找服务体验问题\n活动优化｜改善用户参与过程\n体验复盘｜分析整体体验效果','用户与产品的接触越来越复杂，从注册到使用再到售后都影响体验，因此企业需要专门的人持续优化整个用户体验过程。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',10,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_content' LIMIT 1),'文案策划','1','用文字为品牌和产品创造吸引力','根据品牌、产品或活动需求构思文字内容，用标题、故事、广告语等方式准确传递信息，并吸引目标人群关注。','寻找灵感｜了解热点和用户\n内容构思｜确定文字表达方向\n文案创作｜完成主题文字内容\n修改优化｜根据反馈调整文案','信息越来越多，人们注意力越来越有限，企业需要用更有吸引力的文字讲清产品和品牌价值，因此产生了文案策划工作。',NULL,NULL,'品牌运营专员','数字营销专员','文案策划','IP内容策划',NULL,NULL,NULL,NULL,'C',NULL,'1',1,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_content' LIMIT 1),'短视频编导','1','把一个好想法变成精彩短视频','根据主题策划短视频内容，设计故事、镜头和拍摄流程，把一个想法组织成具有观看吸引力的短视频作品。','选题策划｜确定视频创作主题\n脚本设计｜安排故事和镜头\n现场拍摄｜指导视频拍摄过程\n效果复盘｜分析视频传播效果','短视频成为重要的信息和娱乐方式，一条视频背后需要有人设计主题、故事和镜头，于是形成了短视频编导这一岗位。',NULL,NULL,'视频剪辑师','直播内容策划','短视频编导','摄影师',NULL,NULL,NULL,NULL,'C',NULL,'1',2,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_content' LIMIT 1),'IP内容策划','1','让一个IP拥有持续发展的内容故事','围绕一个人物、形象或品牌设计持续的故事和内容，让IP拥有鲜明特点，并不断产生新的传播内容。','内容构思｜寻找IP创作方向\n故事设计｜规划人物故事内容\n内容制作｜推动IP内容落地\n用户反馈｜观察粉丝互动情况','一个形象想要长期受到关注，需要持续产生故事和内容，因此企业和平台需要专门的人围绕IP规划长期内容。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',3,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_content' LIMIT 1),'视频剪辑师','1','把零散素材剪成完整精彩的视频','将拍摄得到的画面、声音、音乐和文字等素材重新组合，通过剪辑、配乐和包装形成完整的视频作品。','素材整理｜整理拍摄视频素材\n画面剪辑｜选择合适视频片段\n声音包装｜添加音乐和声音\n成片调整｜完善最终视频效果','手机和专业设备让视频生产越来越普遍，但拍摄素材通常不能直接使用，需要通过剪辑、配乐和包装变成完整作品。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',4,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
