INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_content' LIMIT 1),'直播内容策划','1','设计直播内容让观众愿意留下来','根据直播主题和观众特点设计直播内容、流程和互动环节，让直播更有内容、更有节奏，也更容易吸引观众参与。','主题策划｜确定直播内容方向\n流程设计｜安排直播环节内容\n互动设计｜设计观众参与方式\n内容复盘｜总结直播内容效果','直播从简单聊天逐渐发展为专业内容生产，需要持续设计主题、流程和互动方式，因此出现了专门负责直播内容创意的岗位。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',8,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
