INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_content' LIMIT 1),'无人机群飞行规划','1','设计无人机群协同飞行的任务方案','根据拍摄、表演或作业任务设计多架无人机的飞行路线和配合方式，让无人机能够按照计划完成协同飞行。','任务分析｜了解飞行任务要求\n路线设计｜规划无人机飞行路线\n模拟测试｜检查飞行方案效果\n现场协调｜保障飞行任务执行','无人机从单机拍摄逐渐走向编队表演、巡检和大型活动，需要提前设计多架无人机的协同行动，因此产生了新的规划工作。',NULL,NULL,'无人机飞手','无人机应用工程师','无人机群飞行规划','无人机航拍师',NULL,NULL,NULL,NULL,'C',NULL,'1',10,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_marketing' LIMIT 1),'直播运营','1','让直播间吸引更多人并持续增长','负责直播间的日常运营，包括内容安排、活动策划、用户互动和数据分析等，让直播间持续吸引和留住观众。','直播准备｜检查直播内容流程\n现场管理｜关注直播整体运行\n用户互动｜观察观众参与情况\n数据复盘｜分析直播运营结果','直播从个人娱乐发展成商业经营，一个直播间需要持续管理内容、用户和数据，因此企业需要专门人员保障直播业务正常增长。',NULL,NULL,'直播运营','数字营销专员','直播销售员','达人商务',NULL,NULL,NULL,NULL,'A',NULL,'1',1,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_marketing' LIMIT 1),'电商运营','1','让商品在网络平台卖得更好','负责网络店铺和商品的日常经营，通过商品展示、活动推广、用户维护等方式提升店铺的关注度和销售表现。','商品管理｜检查商品线上信息\n活动策划｜设计店铺促销活动\n用户分析｜了解消费者购买情况\n销售复盘｜分析店铺经营数据','消费者越来越习惯在线购物，但商品上架后并不会自动产生销量，需要有人经营店铺、优化商品和吸引消费者。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',2,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_marketing' LIMIT 1),'直播销售员','1','通过直播介绍商品并与顾客互动','在直播过程中介绍商品特点、使用方法和优惠信息，与观众互动答疑，引导有需求的消费者完成购买。','商品准备｜熟悉商品特点信息\n直播介绍｜展示商品使用效果\n互动答疑｜回答消费者问题\n成交跟进｜协助消费者完成购买','传统购物从线下门店延伸到直播间，消费者可以边看边咨询和购买，因此销售人员也逐渐进入直播这一新的商业场景。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',3,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
