INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_marketing' LIMIT 1),'达人商务','1','帮助品牌与合适的达人建立合作','寻找适合品牌合作的网络达人，与达人沟通合作方式、内容要求和项目安排，推动品牌与达人的合作落地。','达人寻找｜寻找合适合作达人\n合作沟通｜洽谈品牌合作需求\n方案确认｜确定合作内容安排\n项目跟进｜推动合作顺利完成','网络达人拥有大量特定兴趣用户，品牌希望借助达人传播产品，因此需要有人负责寻找达人、沟通合作并推动项目落地。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',6,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_marketing' LIMIT 1),'品牌运营专员','1','让品牌形象被更多消费者认识','围绕品牌形象和市场目标策划推广活动，维护品牌在消费者中的认知度，让品牌保持稳定、持续的影响力。','品牌分析｜了解品牌发展情况\n内容规划｜设计品牌传播内容\n活动执行｜组织品牌推广活动\n效果复盘｜分析品牌传播效果','市场上的品牌越来越多，企业不仅要卖产品，还要让消费者记住并认可品牌，因此需要持续经营品牌形象和用户认知。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',7,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_marketing' LIMIT 1),'流量运营专员','1','想办法让更多用户看到品牌和产品','关注用户从哪里来、对什么内容感兴趣，通过活动、内容和渠道优化吸引更多目标用户关注产品或品牌。','流量分析｜查看用户来源数据\n渠道观察｜寻找有效传播渠道\n策略调整｜优化用户获取方式\n效果复盘｜分析流量变化情况','网络平台上的注意力成为重要资源，企业希望让更多目标用户看到自己的内容和产品，因此产生了围绕用户流量进行优化的工作。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',8,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_marketing' LIMIT 1),'PPT设计师','1','把复杂信息设计成清晰好看的演示','将汇报、演讲或方案中的文字和数据重新整理，通过版式、图表和视觉设计，让复杂信息变得清晰、易懂。','需求沟通｜了解汇报展示目的\n内容梳理｜整理文字数据结构\n页面设计｜完成页面视觉排版\n修改完善｜调整最终展示效果','工作和学习中的信息越来越复杂，单纯文字难以快速表达，企业和个人因此需要通过专业的视觉排版提高汇报和沟通效率。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',9,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='digital_marketing' LIMIT 1),'数字乡村经济经理人','1','用数字平台帮助乡村发展特色产业','运用电商、短视频、直播等数字方式帮助乡村推广特色产品和文化资源，连接消费者与乡村产业。','产业了解｜了解当地特色资源\n市场寻找｜寻找线上销售机会\n平台推广｜推广乡村特色产品\n效果跟踪｜关注产品销售情况','互联网和电商让乡村产品能够直接连接城市消费者，因此需要有人利用数字平台帮助乡村销售产品、推广资源和发展产业。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',10,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='professional_service' LIMIT 1),'在线学习管理师','1','帮助学习者规划并管理线上学习过程','根据学习者的目标和学习进度提供过程管理与提醒，帮助学习者合理安排学习计划并保持持续学习。','学习规划｜帮助制定学习计划\n进度跟踪｜了解学习完成情况\n问题提醒｜提醒学习任务进度\n效果反馈｜总结学习阶段成果','学习逐渐从教室延伸到互联网，但线上学习容易缺乏计划和监督，因此需要有人帮助学习者安排过程、保持节奏并完成目标。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',1,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='professional_service' LIMIT 1),'课程顾问','1','根据学习需求推荐合适的课程方案','了解学习者的需求、兴趣和目标，根据实际情况介绍和推荐合适的课程及学习方案，帮助其做出选择。','需求沟通｜了解学习目标需求\n课程介绍｜介绍课程特点内容\n方案推荐｜提供合适学习方案\n学习跟进｜关注后续学习情况','线上课程数量快速增加，学习者面对大量选择容易迷茫，因此需要有人了解需求并帮助他们找到更适合自己的学习方案。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',2,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='professional_service' LIMIT 1),'课程策划','1','把学习需求设计成有趣实用的课程','根据学习对象和学习目标设计课程主题、内容结构和学习活动，把知识和经验组织成易于学习的课程。','需求调研｜了解学习者需求\n内容规划｜设计课程知识结构\n课程开发｜组织制作课程内容\n效果优化｜根据反馈调整课程','知识和经验只有经过合理组织才能成为课程，随着在线教育发展，需要专门的人把学习需求转化为完整的课程内容。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',3,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='professional_service' LIMIT 1),'在线辅导老师','1','在线陪伴并帮助学生解决学习问题','通过线上平台陪伴学生学习，解答学习中的问题，并根据学生情况提供针对性的学习指导和反馈。','学习答疑｜解答学生学习问题\n作业辅导｜帮助学生理解知识\n学习反馈｜了解学生学习情况\n方法指导｜帮助改进学习方法','学习不再局限于学校和教室，学生可以通过互联网获得帮助，因此教师的辅导方式也从线下逐渐延伸到线上。',NULL,NULL,'在线学习管理师','课程顾问','在线辅导老师','企业培训专员',NULL,NULL,NULL,NULL,'C',NULL,'1',4,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='professional_service' LIMIT 1),'企业培训专员','1','为企业员工设计和组织学习培训','根据企业员工和业务发展的需要组织培训，安排课程、讲师和学习活动，帮助员工提升工作所需的知识和能力。','需求了解｜分析员工培训需求\n课程安排｜安排培训课程内容\n培训组织｜协调讲师和学员\n效果评估｜了解培训实际效果','企业需要不断更新员工知识和技能，而传统一次性培训难以满足需求，因此需要专门人员持续组织和管理员工学习。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',5,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='professional_service' LIMIT 1),'线上旅游策划','1','根据需求设计个性化的旅行方案','了解游客的兴趣、预算和时间安排，通过网络提供目的地推荐、路线设计和行程规划等旅行服务。','需求沟通｜了解游客旅行需求\n目的地研究｜寻找合适旅行资源\n路线设计｜规划个性化行程\n方案调整｜根据需求优化路线','人们越来越习惯在网上获取旅游信息，但信息太多反而增加选择难度，因此出现了根据个人需求提供线上旅行规划的服务。',NULL,NULL,'旅行博主','线上旅游策划','户外向导','旅游产品运营',NULL,NULL,NULL,NULL,'B',NULL,'1',6,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='professional_service' LIMIT 1),'互联网医生','1','通过互联网为用户提供医疗健康咨询','通过互联网平台了解患者的健康问题，在符合医疗服务规范的情况下提供线上咨询、健康指导等服务。','线上问诊｜了解用户健康问题\n情况判断｜进行专业健康判断\n健康建议｜提供相关健康指导\n后续跟进｜关注后续健康情况','互联网让医疗健康咨询突破了时间和空间限制，部分健康咨询可以在线完成，因此医疗服务逐渐出现了新的线上服务方式。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',7,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='professional_service' LIMIT 1),'宠物护理','1','为宠物提供日常清洁与基础护理','为宠物提供洗护、清洁、基础护理等服务，关注宠物在护理过程中的状态，让宠物保持整洁和健康。','状态观察｜了解宠物当前状态\n日常清洁｜进行宠物基础清洁\n护理服务｜完成基础护理工作\n主人沟通｜反馈宠物护理情况','宠物逐渐成为家庭成员，人们对宠物生活品质和日常护理的要求提高，因此围绕宠物照护产生了更加细分的服务需求。',NULL,NULL,'宠物训练师','宠物美容师','宠物护理','宠物医生',NULL,NULL,NULL,NULL,'C',NULL,'1',8,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
