INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='professional_service' LIMIT 1),'平面设计师','1','用图形文字创造直观的视觉表达','根据宣传、出版、商业等需求设计海报、宣传册、图片等视觉作品，用图形和文字清晰传达信息。','需求沟通｜了解设计使用场景\n创意构思｜确定视觉表达方向\n设计制作｜完成平面视觉作品\n修改完善｜根据反馈调整作品','企业、媒体和个人每天都需要海报、宣传物料等视觉内容，单纯文字难以满足传播需求，因此产生了专业的视觉设计工作。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',10,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
