INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='freelance_skill' LIMIT 1),'摄影师','1','用镜头记录人与生活中的精彩瞬间','根据客户或创作需求使用相机等设备记录人物、活动、商品或生活场景，通过构图和光影形成具有表现力的照片。','需求沟通｜了解拍摄具体需求\n场景准备｜选择合适拍摄场景\n现场拍摄｜完成照片拍摄工作\n作品整理｜筛选整理拍摄照片','社交媒体、电商和个人记录让人们对高质量影像的需求不断增加，摄影技能因此可以从兴趣发展为接单和商业服务。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',6,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
INSERT INTO gkzh_zycck_career_question(category_id,career_name,has_question,one_line_intro,main_work,day_example,why_exists,career_image_url,question_image_url,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time) SELECT (SELECT category_id FROM gkzh_zycck_category WHERE code='freelance_skill' LIMIT 1),'健康管理师','1','根据个人需求提供健康管理建议','根据个人的生活方式和健康需求提供健康管理建议，帮助人们建立更加规律、合理的健康生活方式。','需求了解｜了解个人健康需求\n情况分析｜分析生活健康状况\n方案建议｜提供健康管理建议\n持续跟踪｜关注后续执行情况','人们开始从“生病后治疗”转向“日常健康管理”，对生活方式和健康习惯的关注增加，因此产生了相关专业服务需求。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'0',7,'0',NOW(),NOW() ON DUPLICATE KEY UPDATE has_question=VALUES(has_question),one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),option_a_career_id=VALUES(option_a_career_id),option_b_career_id=VALUES(option_b_career_id),option_c_career_id=VALUES(option_c_career_id),option_d_career_id=VALUES(option_d_career_id),correct_option_key=VALUES(correct_option_key),explanation=NULL,draw_candidate=VALUES(draw_candidate),sort_order=VALUES(sort_order),status=VALUES(status),update_time=NOW();
