UPDATE gkzh_zycck_career_question q SET q.option_d_career_id=(SELECT x.career_question_id FROM gkzh_zycck_career_question x WHERE x.career_name='健康顾问' AND x.status='0' ORDER BY x.career_question_id LIMIT 1) WHERE q.category_id=(SELECT category_id FROM gkzh_zycck_category WHERE code='freelance_skill' LIMIT 1) AND q.career_name='营养师';
SELECT q.career_name, q.option_a, q.option_b, q.option_c, q.option_d FROM gkzh_zycck_career_question q WHERE q.has_question='1' AND q.draw_candidate='1' AND (q.option_a_career_id IS NULL OR q.option_b_career_id IS NULL OR q.option_c_career_id IS NULL OR q.option_d_career_id IS NULL);
